18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.regex.Pattern;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    /**
60	     * Pragmatic check for a syntactically valid email address: a non-empty local
61	     * part, a single '@', and a domain with at least one dot-separated label.
62	     */
63	    private static final Pattern EMAIL_PATTERN =
64	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        // Validate & normalize the optional email; reject the create when it is present but invalid.
113	        if (!normalizeEmail(ownerFieldsDto)) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
117	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
118	        if (normalizedTelephone == null) {
119	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
120	        }
121	        // Reject the create if any existing owner already uses this telephone (compared in E.164 form).
122	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
123	            .map(Owner::getTelephone)
124	            .map(OwnerRestControllerV1::toE164)
125	            .filter(existing -> existing != null)
126	            .anyMatch(normalizedTelephone::equals);
127	        if (telephoneInUse) {
128	            return new ResponseEntity<>(HttpStatus.CONFLICT);
129	        }
130	        // Reject the create when another owner already shares this owner's last name and address
131	        // (compared case-insensitively with collapsed whitespace), unless the request opts into
132	        // sharing a household.
133	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
134	            String normalizedLastName = normalizeHouseholdKey(ownerFieldsDto.getLastName());
135	            String normalizedAddress = normalizeHouseholdKey(ownerFieldsDto.getAddress());
136	            boolean householdInUse = this.clinicService.findAllOwners().stream()
137	                .anyMatch(existing ->
138	                    normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
139	                        && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress));
140	            if (householdInUse) {
141	                return new ResponseEntity<>(HttpStatus.CONFLICT);
142	            }
143	        }
144	        ownerFieldsDto.setTelephone(normalizedTelephone);
145	        HttpHeaders headers = new HttpHeaders();
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	        // Default the registration date to the server's current date when none was supplied.
148	        if (owner.getRegistrationDate() == null) {
149	            owner.setRegistrationDate(LocalDate.now());
150	        }
151	        // Assign the customer code as '<LAST3>-<NNNN>': the upper-cased first three letters
152	        // of the last name, and a global 4-digit sequence one greater than the current owner count.
153	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
154	        this.clinicService.saveOwner(owner);
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        headers.setLocation(UriComponentsBuilder.newInstance()
157	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
158	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
159	    }
160	
161	    /**
162	     * Validate and normalize the optional owner email in place.
163	     *
164	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
165	     * When present it must be a syntactically valid address; a valid address is
166	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
167	     * present but syntactically invalid, so the caller can reject with 400.
168	     */
169	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
170	        String email = ownerFieldsDto.getEmail();
171	        if (email == null || email.isBlank()) {
172	            ownerFieldsDto.setEmail(null);
173	            return true;
174	        }
175	        String normalized = email.trim().toLowerCase(Locale.ROOT);
176	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
177	            return false;
178	        }
179	        ownerFieldsDto.setEmail(normalized);
180	        return true;
181	    }
182	
183	    /**
184	     * Normalize an owner household field (last name or address) for duplicate detection:
185	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
186	     * A {@code null} value normalizes to the empty string.
187	     */
188	    private static String normalizeHouseholdKey(String value) {
189	        if (value == null) {
190	            return "";
191	        }
192	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
193	    }
194	
195	    /**
196	     * Normalize a telephone number to E.164 form.
197	     *
198	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
199	     * explicit leading {@code '+'} and country code it is kept; otherwise the
200	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
201	     * dropped from the national digits. The result must contain 8 to 15 digits
202	     * after the {@code '+'}.
203	     *
204	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
