48	        try {
49	            byte[] digest = MessageDigest.getInstance("SHA-256")
50	                .digest(key.getBytes(StandardCharsets.UTF_8));
51	            StringBuilder sb = new StringBuilder();
52	            for (int i = 0; i < 4; i++) {
53	                sb.append(String.format("%02X", digest[i]));
54	            }
55	            return sb.toString();
56	        }
57	        catch (java.security.NoSuchAlgorithmException e) {
58	            throw new IllegalStateException(e);
59	        }
60	    }
61	
62	    private static String normalizeHouseholdKey(String value) {
63	        if (value == null) {
64	            return "";
65	        }
66	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
67	    }
